import numpy as np
from scipy.spatial.transform import Rotation as R
q=np.array([0,-1.0472,0,-2.638,0,1.535,-2.32]);a=[0,0,0,0.0825,-0.0825,0,0.088];d=[0.333,0,0.316,0,0.384,0,0.107];al=[0,-np.pi/2,np.pi/2,np.pi/2,-np.pi/2,np.pi/2,np.pi/2]
def trans(x=0,y=0,z=0):
 t=np.eye(4);t[:3,3]=[x,y,z];return t
def rot(ax,ang):
 t=np.eye(4);t[:3,:3]=R.from_rotvec(np.array(ax)*ang).as_matrix();return t
for typ in ['mdh','dh']:
 t=np.eye(4)
 for i in range(7):
  if typ=='mdh': t=t@rot([1,0,0],al[i])@trans(x=a[i])@rot([0,0,1],q[i])@trans(z=d[i])
  else:t=t@rot([0,0,1],q[i])@trans(z=d[i])@trans(x=a[i])@rot([1,0,0],al[i])
 print(typ,t[:3,3],R.from_matrix(t[:3,:3]).as_quat())
 for zrot in [0,np.pi/2,-np.pi/2,np.pi]:
  tw=rot([0,0,1],zrot)@t;tw[:3,3]+=[0,-.4,.78]
  print(zrot,tw[:3,3],R.from_matrix(tw[:3,:3]).as_quat())
